{"file_path":"src/document.js","content":"/**
 * The document tree the parser builds, plus the path bookkeeping shared by
 * error messages and the `keys` output.
 *
 * A node is a plain object tagged by `t`:
 *   - `table`: `{ t: 'table', map: Map<string, Node>, headerDefined }`
 *   - `aot` (array of tables): `{ t: 'aot', items: Node[] }`, each a `table`
 *   - `array`: `{ t: 'array', items: Node[] }`
 *   - `string` / `integer` / `float` / `boolean`: `{ t, v }`
 *
 * A path is an array of segments, each `{ type: 'key', name }` or
 * `{ type: 'idx', i }`, describing where a node sits relative to the root.
 */

export function makeTable() {
  return { t: 'table', map: new Map(), headerDefined: false }
}

export function pathString(path) {
  let out = ''
  for (const seg of path) {
    if (seg.type === 'key') {
      if (out !== '') out += '.'
      out += seg.name
    } else {
      out += `[${seg.i}]`
    }
  }
  return out
}

/**
 * Walks all but the last of `names` starting from `table`, creating tables
 * along the way and stepping into the last element when a name already holds
 * an array of tables. `path` is mutated to describe the walk (for error
 * messages); the base path passed in is left untouched by the caller's copy.
 * Throws when a name already holds something other than a table or an array
 * of tables.
 */
export function walkIntermediate(table, path, names, ParseErrorCtor, line) {
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path.push({ type: 'key', name })
    const existing = table.map.get(name)
    if (existing === undefined) {
      const next = makeTable()
      table.map.set(name, next)
      table = next
    } else if (existing.t === 'table') {
      table = existing
    } else if (existing.t === 'aot') {
      const idx = existing.items.length - 1
      table = existing.items[idx]
      path.push({ type: 'idx', i: idx })
    } else {
      throw new ParseErrorCtor(line, `${pathString(path)} is not a table`)
    }
  }
  return table
}

/**
 * A best-effort path computation used while parsing a value, before the
 * assignment itself has run. It never creates or mutates anything and simply
 * mirrors the existing structure so a value nested inside (an inline table or
 * array) reports the path it will end up at. If the walk meets something
 * unexpected it stops mirroring the real tree; the later real assignment is
 * what actually enforces correctness and raises the precise error.
 */
export function peekPath(table, basePath, names) {
  const path = basePath.slice()
  let t = table
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path.push({ type: 'key', name })
    const existing = t ? t.map.get(name) : undefined
    if (existing && existing.t === 'table') {
      t = existing
    } else if (existing && existing.t === 'aot') {
      const idx = existing.items.length - 1
      t = existing.items[idx]
      path.push({ type: 'idx', i: idx })
    } else {
      t = null
    }
  }
  path.push({ type: 'key', name: names[names.length - 1] })
  return path
}

/**
 * Assigns `value` at the dotted `names` inside `table`, creating the tables
 * the dots walk through. `basePath` is the path to `table` itself. Throws
 * when the final name already holds anything, or a dot walks through a name
 * holding something other than a table or an array of tables.
 */
export function assignValue(table, basePath, names, value, ParseErrorCtor, line) {
  const path = basePath.slice()
  const target = walkIntermediate(table, path, names, ParseErrorCtor, line)
  const last = names[names.length - 1]
  path.push({ type: 'key', name: last })
  if (target.map.has(last)) {
    throw new ParseErrorCtor(line, `key ${pathString(path)} is defined twice`)
  }
  target.map.set(last, value)
}
"}

