{"file_path":"src/lexer.js","content":"import { ParseError } from './errors.js'
import { makeTable, peekPath, assignValue } from './document.js'

const BARE_NAME = /[A-Za-z0-9_-]/
const DIGITS = String.raw`\d+(?:_\d+)*`
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGITS}(?:\\.${DIGITS}(?:[eE][+-]?${DIGITS})?|[eE][+-]?${DIGITS})$`
)

const ESCAPES = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', '0': '\0' }

/**
 * A cursor over one line of the document. All parsing helpers for names,
 * strings and values live here; the document-shaping logic (tables, arrays
 * of tables) lives in parser.js.
 */
export class Scanner {
  constructor(line, lineNo) {
    this.s = line
    this.i = 0
    this.n = line.length
    this.line = lineNo
  }

  fail(reason) {
    throw new ParseError(this.line, reason)
  }

  eof() {
    return this.i >= this.n
  }

  peek() {
    return this.s[this.i]
  }

  skipWs() {
    while (!this.eof() && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True (and leaves the cursor past whitespace) at end of line or a comment. */
  atEnd() {
    this.skipWs()
    return this.eof() || this.s[this.i] === '#' || this.s[this.i] === ';'
  }

  parseName() {
    this.skipWs()
    if (this.eof()) this.fail('expected a name')
    const c = this.s[this.i]
    if (c === '"') return this.readBasicString()
    if (c === "'") return this.readLiteralString()
    if (!BARE_NAME.test(c)) this.fail('expected a name')
    const start = this.i
    while (!this.eof() && BARE_NAME.test(this.s[this.i])) this.i++
    return this.s.slice(start, this.i)
  }

  parseDottedName() {
    const names = [this.parseName()]
    while (true) {
      this.skipWs()
      if (this.eof() || this.s[this.i] !== '.') break
      this.i++
      this.skipWs()
      names.push(this.parseName())
    }
    return names
  }

  readBasicString() {
    this.i++ // opening quote
    let out = ''
    while (true) {
      if (this.eof()) this.fail('unterminated string')
      const c = this.s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        const next = this.s[this.i + 1]
        if (next === undefined) this.fail('unterminated string')
        if (next === 'u') {
          const hex = this.s.slice(this.i + 2, this.i + 6)
          if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) this.fail('unterminated string')
          out += String.fromCharCode(parseInt(hex, 16))
          this.i += 6
          continue
        }
        if (Object.prototype.hasOwnProperty.call(ESCAPES, next)) {
          out += ESCAPES[next]
          this.i += 2
          continue
        }
        this.fail(`invalid escape \\${next}`)
      }
      out += c
      this.i++
    }
  }

  readLiteralString() {
    this.i++ // opening quote
    const start = this.i
    while (true) {
      if (this.eof()) this.fail('unterminated string')
      if (this.s[this.i] === "'") {
        const out = this.s.slice(start, this.i)
        this.i++
        return out
      }
      this.i++
    }
  }

  readBareToken() {
    const start = this.i
    while (!this.eof() && !' \t,]}'.includes(this.s[this.i])) this.i++
    return this.s.slice(start, this.i)
  }

  /**
   * Parses a value at the cursor. `path` is the (best-effort) path this
   * value will live at, threaded through so inline tables and arrays can
   * report accurate paths for their own nested key errors.
   */
  parseValue(path) {
    this.skipWs()
    if (this.eof() || ',]}'.includes(this.s[this.i])) this.fail('expected a value')
    const c = this.s[this.i]
    if (c === '"') return { t: 'string', v: this.readBasicString() }
    if (c === "'") return { t: 'string', v: this.readLiteralString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    const token = this.readBareToken()
    if (token === 'true') return { t: 'boolean', v: true }
    if (token === 'false') return { t: 'boolean', v: false }
    if (INT_RE.test(token)) return { t: 'integer', v: Number(token.replace(/_/g, '')) }
    if (FLOAT_RE.test(token)) return { t: 'float', v: Number(token.replace(/_/g, '')) }
    this.fail(`invalid value ${token}`)
  }

  parseArray(path) {
    this.i++ // '['
    const items = []
    let index = 0
    while (true) {
      this.skipWs()
      if (this.eof()) this.fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return { t: 'array', items }
      }
      items.push(this.parseValue(path.concat([{ type: 'idx', i: index++ }])))
      this.skipWs()
      if (this.eof()) this.fail('unterminated array')
      if (this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (this.s[this.i] === ']') {
        this.i++
        return { t: 'array', items }
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTable(path) {
    this.i++ // '{'
    const table = makeTable()
    this.skipWs()
    if (!this.eof() && this.s[this.i] === '}') {
      this.i++
      return table
    }
    while (true) {
      this.skipWs()
      const names = this.parseDottedName()
      this.skipWs()
      if (this.eof() || this.s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      const valuePath = peekPath(table, path, names)
      const value = this.parseValue(valuePath)
      assignValue(table, path, names, value, ParseError, this.line)
      this.skipWs()
      if (this.eof()) this.fail('unterminated inline table')
      if (this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (this.s[this.i] === '}') {
        this.i++
        return table
      }
      this.fail('unterminated inline table')
    }
  }
}
"}

