{"file_path":"src/parser.js","content":"import { ParseError } from './errors.js'
import { Scanner } from './lexer.js'
import { makeTable, pathString, peekPath, walkIntermediate, assignValue } from './document.js'

function resolveHeaderSingle(root, names, line) {
  const path = []
  const table = walkIntermediate(root, path, names, ParseError, line)
  const last = names[names.length - 1]
  path.push({ type: 'key', name: last })
  const existing = table.map.get(last)
  if (existing === undefined) {
    const next = makeTable()
    next.headerDefined = true
    table.map.set(last, next)
    return { table: next, path }
  }
  if (existing.t === 'table') {
    if (existing.headerDefined) throw new ParseError(line, `table ${pathString(path)} is defined twice`)
    existing.headerDefined = true
    return { table: existing, path }
  }
  throw new ParseError(line, `${pathString(path)} is not a table`)
}

function resolveHeaderArray(root, names, line) {
  const path = []
  const table = walkIntermediate(root, path, names, ParseError, line)
  const last = names[names.length - 1]
  path.push({ type: 'key', name: last })
  const existing = table.map.get(last)
  let aot
  if (existing === undefined) {
    aot = { t: 'aot', items: [] }
    table.map.set(last, aot)
  } else if (existing.t === 'aot') {
    aot = existing
  } else {
    throw new ParseError(line, `${pathString(path)} is not an array of tables`)
  }
  const next = makeTable()
  aot.items.push(next)
  path.push({ type: 'idx', i: aot.items.length - 1 })
  return { table: next, path }
}

function isBlankOrComment(raw) {
  const trimmed = raw.replace(/^[ \t]*/, '')
  return trimmed === '' || trimmed[0] === '#' || trimmed[0] === ';'
}

function parseHeaderLine(sc, root, lineNo) {
  sc.i++ // '['
  let isArray = false
  if (!sc.eof() && sc.peek() === '[') {
    isArray = true
    sc.i++
  }
  const names = sc.parseDottedName()
  sc.skipWs()
  if (sc.eof() || sc.s[sc.i] !== ']') sc.fail('unterminated table header')
  sc.i++
  if (isArray) {
    if (sc.eof() || sc.s[sc.i] !== ']') sc.fail('unterminated table header')
    sc.i++
  }
  if (!sc.atEnd()) sc.fail('trailing text after a table header')
  return isArray ? resolveHeaderArray(root, names, lineNo) : resolveHeaderSingle(root, names, lineNo)
}

function parseAssignLine(sc, current, currentPath, lineNo) {
  const names = sc.parseDottedName()
  sc.skipWs()
  if (sc.eof() || sc.s[sc.i] !== '=') sc.fail('expected key = value')
  sc.i++
  const valuePath = peekPath(current, currentPath, names)
  const value = sc.parseValue(valuePath)
  if (!sc.atEnd()) sc.fail('trailing text after a value')
  assignValue(current, currentPath, names, value, ParseError, lineNo)
}

/**
 * Parses the whole document (already split into lines, with the empty tail
 * of a trailing newline dropped) into a root table node. Throws ParseError
 * on the first problem found, scanning lines top to bottom.
 */
export function parseDocument(lines) {
  const root = makeTable()
  let current = root
  let currentPath = []
  for (let idx = 0; idx < lines.length; idx++) {
    const raw = lines[idx]
    if (isBlankOrComment(raw)) continue
    const lineNo = idx + 1
    const sc = new Scanner(raw, lineNo)
    sc.skipWs()
    if (sc.peek() === '[') {
      const result = parseHeaderLine(sc, root, lineNo)
      current = result.table
      currentPath = result.path
    } else {
      parseAssignLine(sc, current, currentPath, lineNo)
    }
  }
  return root
}
"}

