{"file_path":"src/format.js","content":"import { pathString } from './document.js'

function indent(level) {
  return '  '.repeat(level)
}

function sortedNames(table) {
  return [...table.map.keys()].sort()
}

/** Renders a node as JSON text; `level` is the level of the key line above it. */
function jsonify(node, level) {
  if (node.t === 'table') {
    const names = sortedNames(node)
    if (names.length === 0) return '{}'
    const lines = names.map(
      (name) => `${indent(level + 1)}${JSON.stringify(name)}: ${jsonify(node.map.get(name), level + 1)}`
    )
    return `{\n${lines.join(',\n')}\n${indent(level)}}`
  }
  if (node.t === 'aot' || node.t === 'array') {
    if (node.items.length === 0) return '[]'
    const lines = node.items.map((item) => `${indent(level + 1)}${jsonify(item, level + 1)}`)
    return `[\n${lines.join(',\n')}\n${indent(level)}]`
  }
  return JSON.stringify(node.v)
}

export function toJson(root) {
  return `${jsonify(root, 0)}\n`
}

function walkKeys(node, path, out) {
  if (node.t === 'table') {
    out.push(`${pathString(path)} table`)
    for (const name of sortedNames(node)) {
      walkKeys(node.map.get(name), path.concat([{ type: 'key', name }]), out)
    }
  } else if (node.t === 'aot' || node.t === 'array') {
    out.push(`${pathString(path)} array`)
    node.items.forEach((item, i) => walkKeys(item, path.concat([{ type: 'idx', i }]), out))
  } else {
    out.push(`${pathString(path)} ${node.t}`)
  }
}

export function toKeys(root) {
  const out = []
  for (const name of sortedNames(root)) {
    walkKeys(root.map.get(name), [{ type: 'key', name }], out)
  }
  return out.length ? out.join('\n') + '\n' : ''
}
"}

